# per-layer rel norm for LM attention / mlp, and vision layers
def layer_profile(comp, is_vision):
    out = {}
    for n in NAMES:
        if COMPONENT[n]!=comp: continue
        if is_vision != n.startswith('vision_tower'): continue
        L = LAYER[n]
